namespace Fanex.Tarus.Customer.Business.AutoSuspend
{
    using System;
    using Fanex.Tarus.Customer.Criteria.AutoSuspend;
    using Fanex.Tarus.Customer.DataAccess.AutoSuspend;
    using Fanex.Tarus.Customer.Entities.AutoSuspend;
    using Fanex.Tarus.Infrastructure.Extensions;
    using Sunplus.Accounting.Entities;

    /// <summary>
    /// TODO: Update summary.
    /// </summary>
    public class AutoSuspendService : IAutoSuspendService
    {
        private readonly IAutoSuspendRepository _autoSuspendRepository;

        public AutoSuspendService()
            : this(null)
        {
        }

        public AutoSuspendService(IAutoSuspendRepository autoSuspendRepository)
        {
            _autoSuspendRepository = autoSuspendRepository ?? new AutoSuspendRepository();
        }

        /// <summary>
        /// Gets the customer status.
        /// </summary>
        /// <param name="criteria">The criteria.</param>
        /// <returns>Customer Info.</returns>
        public CustomerInfo GetCustomerStatus(GetCustomerStatusCriteria criteria)
        {
            try
            {
                var rawData = _autoSuspendRepository.GetCustomerStatus(criteria);
                return rawData;
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }

            return null;
        }

        /// <summary>
        /// Updates the customer status.
        /// </summary>
        /// <param name="criteria">The criteria.</param>
        /// <returns>Update Result.</returns>
        public Result UpdateCustomerStatus(UpdateCustomerStatusCriteria criteria)
        {
            try
            {
                Result updateResult = new Result();
                if (criteria.UplineAutoSuspendSoccer &&
                    criteria.UplineAutoSuspendOtherSports)
                {
                    updateResult.ErrorCode = 1;
                    updateResult.ErrorMessage = "Upline has been auto suspended";
                    return updateResult;
                }

                updateResult = _autoSuspendRepository.UpdateCustomerStatus(criteria);
                if (updateResult.ErrorCode == 0)
                {
                    updateResult.ErrorMessage = "Auto suspend status updated successfully";
                }

                return updateResult;
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }

            return null;
        }
    }
}
